let celsius = 20;

<input
  id="celsius"
  type="number"
  value=celsius
  on-input=(e) => {
    celsius = Number(e.target.value) || 0;
  }
/>

<div id="fahrenheit">
  ${celsius * 9 / 5 + 32}
</div>

<button id="warmer" on-click=() => {
  celsius++;
}>
  Warmer
</button>

$ {
  let activeIndex = 0;
}

<div>
  <div role="tablist">
    <for|tab, i| of=input.tab>
      <button
        aria-selected=(i === activeIndex ? "true" : undefined)
        on-click() {
          activeIndex = i;
        }
      >
        ${tab.label}
      </button>
    </for>
  </div>

  <div id="panel">
    ${input.tab[activeIndex]?.renderBody()}
  </div>
</div>

<@slot name="tab" label />

