import { getProduct } from "../../../catalog.js";

export async function get({ params }) {
  const product = getProduct(params.id);

  if (!product) {
    return new Response(JSON.stringify({ error: "not found" }), {
      status: 404,
      headers: { "content-type": "application/json" },
    });
  }

  return new Response(JSON.stringify(product), {
    headers: { "content-type": "application/json" },
  });
}

import { addEntry } from "../../store.js";

export async function post(req) {
  const formData = await req.formData();
  const message = formData.get("message");

  if (message && message.trim()) {
    addEntry(message.trim());
  }

  return new Response(null, {
    status: 303,
    headers: {
      "Location": "/guestbook"
    }
  });
}

import { addEntry } from "../store.js";

export async function POST(req, res) {
  const formData = await req.formData();
  const message = formData.get("message");

  if (message && message.trim()) {
    addEntry(message);
  }

  res.writeHead(302, { 'Location': '/guestbook' });
  res.end();
}

import { cities } from "../cities.js";

let searchQuery = "";
let filteredCities = cities.filter(city =>
  city.toLowerCase().includes(searchQuery.toLowerCase())
);

<input
  id="q"
  type="text"
  placeholder="Search cities..."
  on-input(event) {
    searchQuery = event.target.value;
  }
/>

<ul id="results">
  <for|city| of=filteredCities>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${filteredCities.length} matches</div>

export default function middleware(input) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
  }
}

export async function onRequest({ request }) {
  const url = new URL(request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }
}
